"""Owned loopback TCP/UDP transport relays; drop only fixture traffic, never host firewall changes."""
import socket,threading,select,contextlib
from alertmanager_native import free_port
class Relay:
 def __init__(self,target):
  self.target=('127.0.0.1',target);self.port=free_port();self.enabled={'tcp','udp'};self.dropped={'tcp':0,'udp':0};self.stop=threading.Event();self.threads=[];self.flows=set();self.lock=threading.Lock()
 def __enter__(self):
  self.tcp=socket.socket();self.tcp.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1);self.tcp.bind(('127.0.0.1',self.port));self.tcp.listen(8);self.tcp.settimeout(.1)
  self.udp=socket.socket(socket.AF_INET,socket.SOCK_DGRAM);self.udp.bind(('127.0.0.1',self.port));self.udp.settimeout(.1)
  for fn in (self.tcp_loop,self.udp_loop):
   thread=threading.Thread(target=fn,daemon=True);thread.start();self.threads.append(thread)
  return self
 def enable(self,protocols):
  value=set(protocols)
  if not value<={'tcp','udp'}:raise ValueError('only owned TCP/UDP transports')
  self.enabled=value
  if 'tcp' not in value:
   with self.lock:
    for conn in tuple(self.flows):
     with contextlib.suppress(OSError):conn.shutdown(socket.SHUT_RDWR)
 def tcp_loop(self):
  while not self.stop.is_set():
   try:client,_=self.tcp.accept()
   except socket.timeout:continue
   except OSError:return
   if 'tcp' not in self.enabled:self.dropped['tcp']+=1;client.close();continue
   thread=threading.Thread(target=self.flow,args=(client,),daemon=True);thread.start();self.threads.append(thread)
 def flow(self,client):
  peer=None
  try:
   peer=socket.create_connection(self.target,timeout=.2)
   with self.lock:self.flows.update((client,peer))
   while not self.stop.is_set() and 'tcp' in self.enabled:
    ready,_,_=select.select([client,peer],[],[],.1)
    for source in ready:
     data=source.recv(65536)
     if not data:return
     (peer if source is client else client).sendall(data)
  except OSError:pass
  finally:
   with self.lock:self.flows.discard(client);self.flows.discard(peer)
   client.close()
   if peer is not None:peer.close()
 def udp_loop(self):
  sender=None
  while not self.stop.is_set():
   try:data,address=self.udp.recvfrom(65536)
   except socket.timeout:continue
   except OSError:return
   if 'udp' not in self.enabled:self.dropped['udp']+=1;continue
   if address==self.target:
    if sender is not None:
     with contextlib.suppress(OSError):self.udp.sendto(data,sender)
   else:
    sender=address
    with contextlib.suppress(OSError):self.udp.sendto(data,self.target)
 def __exit__(self,*args):
  self.stop.set();self.enable(());self.tcp.close();self.udp.close()
  for thread in self.threads:thread.join(timeout=.3)
